{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["AI coding agent", "Shell command executor", "Repository reader", "Issue comment reader", "Branch push / git client", "Developer request interface"],
    "dataStores": ["Source code repositories", "Agent context / conversation state"],
    "externalServices": ["LLM provider", "Git hosting (all repositories)", "Jira issue comments"],
    "trustBoundaries": ["Untrusted issue comments and repository content into agent context", "Agent reasoning into shell execution", "Agent into git hosting with write-all token", "Developer into agent instruction channel"],
    "dataClasses": ["credentials", "secrets"],
    "exposure": "internal",
    "llmFeatures": true
  },
  "threats": [
    {
      "stride": "Tampering",
      "title": "Hidden instructions in issue comments make the agent push attacker-chosen code",
      "scenario": "Anyone who can comment on an issue (or open a PR touching a file the agent reads) writes text that looks like an instruction, e.g. 'also add this dependency' or 'run this setup script'. The agent reads the comment as part of its task, runs the shell commands and pushes a branch containing the attacker's change. Because the agent's token has write access to all repositories, a comment on one low-value project can be used to modify code anywhere.",
      "component": "AI coding agent (issue comment and repository ingestion)",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        { "quote": "The agent reads the repository and issue comments, and can run shell commands and push branches using a token with write access to all repositories." }
      ],
      "asvs": [],
      "cwe": ["CWE-94"],
      "plainLanguage": "An outsider can hide orders in an issue comment, and the robot developer will follow them and change your code.",
      "requirement": {
        "title": "Treat issue comments and repository content as untrusted data, not instructions",
        "given": "an AI coding agent that reads repository files and issue comments while fixing a bug",
        "when": "that content contains text that resembles instructions or tool calls",
        "then": "the content is passed to the model as clearly delimited untrusted data, instructions in it are never acted on, and any shell command or push derived from such content is blocked and surfaced to a human"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "One shared token with write access to every repository gives unlimited blast radius",
      "scenario": "The agent holds a single token that can write to all repositories. Any successful hijack, bug or misuse of the agent, or anyone who can read the token out of the agent's environment via a shell command, can modify or backdoor code in unrelated projects including release and infrastructure repositories. There is no scoping to the repository the bug actually lives in.",
      "component": "Agent git credential (write-all token)",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "can run shell commands and push branches using a token with write access to all repositories" }
      ],
      "asvs": [],
      "cwe": ["CWE-250"],
      "plainLanguage": "The agent carries one master key to every codebase, so any mistake or abuse affects all projects at once.",
      "requirement": {
        "title": "Scope agent git credentials to the single repository and branch of the current task",
        "given": "an agent run started for a specific bug in a specific repository",
        "when": "the agent needs to read code or push a branch",
        "then": "it receives a short-lived credential limited to that repository and to non-protected branches only, and the credential is never exposed to the shell environment the agent can read"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Shell access lets the agent run anything on the build host",
      "scenario": "The design gives the agent the ability to run shell commands with no stated restriction. An attacker who steers the agent, or a model mistake, can run commands that read environment variables and CI secrets, pivot to internal networks reachable from the host, install persistence, or tamper with the host's git configuration and hooks so later runs are compromised.",
      "component": "Shell command executor",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "can run shell commands and push branches using a token with write access to all repositories" }
      ],
      "asvs": [],
      "cwe": ["CWE-78"],
      "plainLanguage": "The agent can run any command on the machine, so taking over the agent means taking over that machine.",
      "requirement": {
        "title": "Run agent shell commands in a disposable, locked-down sandbox",
        "given": "an agent that executes shell commands to fix bugs",
        "when": "any command is executed",
        "then": "it runs in a single-use container with no host credentials mounted, no access to other repositories' checkouts, an allow-listed command set, and the sandbox is destroyed at the end of the run"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Agent can be used to copy source code and secrets out to an attacker",
      "scenario": "With shell access the agent can reach the network. An attacker who plants instructions in a comment or a repository file can have the agent print environment variables and the git token, or archive private source, and send it to an external endpoint, or simply commit it into a public branch it is allowed to push. Nothing in the design limits egress or what the agent may read.",
      "component": "Shell command executor / network egress",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The agent reads the repository and issue comments, and can run shell commands and push branches using a token with write access to all repositories." }
      ],
      "asvs": [],
      "cwe": ["CWE-200"],
      "plainLanguage": "The agent could be tricked into mailing your private code and access keys to a stranger.",
      "requirement": {
        "title": "Deny-by-default network egress from the agent sandbox",
        "given": "an agent sandbox that executes shell commands",
        "when": "a command attempts an outbound network connection",
        "then": "only an allow-list of hosts needed for the task (package registry, the one target repository, the LLM endpoint) is reachable, all other egress is dropped and the attempt is reported"
      }
    },
    {
      "stride": "Tampering",
      "title": "Poisoned repository files steer every later agent run",
      "scenario": "An attacker with commit access to any repository the agent reads, or who lands one accepted pull request, adds instructions to a file the agent always ingests (README, contributing guide, config, test fixture). Every subsequent run that reads that repository inherits the attacker's goal, so a single one-off change becomes persistent control of the agent across tasks and projects.",
      "component": "Repository reader / agent context",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The agent reads the repository and issue comments" }
      ],
      "asvs": [],
      "cwe": ["CWE-1427"],
      "plainLanguage": "A booby-trapped file in the codebase can keep bossing the agent around on every future job.",
      "requirement": {
        "title": "Do not let repository content modify agent goals or configuration",
        "given": "an agent that ingests files from the repository under repair",
        "when": "those files contain agent directives, tool configuration or prompt-like text",
        "then": "the directives are ignored, agent configuration is loaded only from a trusted source outside the repository, and the agent's goal for the run is fixed at dispatch time"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Agent pushes cannot be traced back to the developer who asked",
      "scenario": "All branches are pushed with one shared agent token, so commits and pushes are attributed to the agent rather than to the developer who requested the fix or to the issue that triggered it. After a malicious or damaging change is pushed, responders cannot tell which request produced it, which comment influenced it, or which commands the agent ran, which makes containment and cleanup guesswork.",
      "component": "Branch push / git client",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        { "quote": "push branches using a token with write access to all repositories" }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "Every change looks like it came from 'the agent', so nobody can tell who or what actually caused it.",
      "requirement": {
        "title": "Bind each agent run and push to the requesting human and the source task",
        "given": "an agent run triggered by a developer on a specific issue",
        "when": "the agent pushes a branch or runs a shell command",
        "then": "the run id, requesting user, issue key, commands executed and the content sources ingested are recorded immutably and referenced in the commit trailer"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Developers trust agent branches and merge a backdoor",
      "scenario": "Because the output arrives as a normal branch from a trusted internal tool, reviewers skim it. An attacker who hijacked the agent through a comment or poisoned file hides a small change, such as a weakened auth check or an added dependency, in an otherwise plausible bug fix. The change reaches main through the normal merge path and gains the privileges of the production code.",
      "component": "Developer review of agent-authored branches",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Developers ask an AI coding agent to fix bugs." }
      ],
      "asvs": [],
      "cwe": ["CWE-1357"],
      "plainLanguage": "People assume the agent's pull request is safe and merge a hidden backdoor without a real review.",
      "requirement": {
        "title": "Require human review of agent branches with the agent's inputs disclosed",
        "given": "a branch pushed by the coding agent",
        "when": "it is opened for merge",
        "then": "the pull request is labelled as agent-authored, lists the untrusted sources and shell commands used, cannot be approved by the agent identity, and requires approval from a human other than the requester for changes touching auth, dependencies or CI"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Unbounded agent runs burn the build host and the shared token",
      "scenario": "Nothing bounds how long the agent runs, how many commands it executes or how many branches it pushes. A crafted bug report that keeps the agent looping, or a hijack that tells it to mine or to spam pushes, exhausts the build host and the git hosting rate limits for the shared write-all token, which blocks the agent and any other automation relying on that token for all teams.",
      "component": "Agent run orchestration",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "can run shell commands and push branches using a token with write access to all repositories" }
      ],
      "asvs": [],
      "cwe": ["CWE-400"],
      "plainLanguage": "One runaway agent job can hog the machine and lock the shared account out for everyone.",
      "requirement": {
        "title": "Hard limits per agent run",
        "given": "an agent run executing shell commands and pushes",
        "when": "it exceeds a configured wall-clock, command-count, CPU/memory or push quota",
        "then": "the run is terminated, the sandbox destroyed and the owning developer notified, without affecting other runs"
      }
    }
  ]
}

